package com.wipro.spring; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import org.springframework.ui.Model; @Controller public class MarksController { @GetMapping("/") public String form(){return "index";} @PostMapping("/submit") public String submit(@RequestParam int science,@RequestParam int maths,@RequestParam int english,Model model){model.addAttribute("total",science+maths+english);return "result";} }